1	import express, { type Express, type Request, type Response, type NextFunction } from "express";
2	import cors from "cors";
3	import pinoHttp from "pino-http";
4	import { clerkMiddleware, getAuth } from "@clerk/express";
5	import { and, eq } from "drizzle-orm";
6	import { db, appUsers, workspaceMembers } from "@workspace/db";
7	import {
8	  CLERK_PROXY_PATH,
9	  clerkProxyMiddleware,
10	} from "./middlewares/clerkProxyMiddleware";
11	import router from "./routes";
12	import { logger } from "./lib/logger";
13	
14	const app: Express = express();
15	
16	app.use(
17	  pinoHttp({
18	    logger,
19	    serializers: {
20	      req(req) {
21	        return {
22	          id: req.id,
23	          method: req.method,
24	          url: req.url?.split("?")[0],
25	        };
26	      },
27	      res(res) {
28	        return {
29	          statusCode: res.statusCode,
30	        };
31	      },
32	    },
33	  }),
34	);
35	
36	app.use(CLERK_PROXY_PATH, clerkProxyMiddleware());
37	
38	app.use(cors({ credentials: true, origin: true }));
39	app.use(express.json({ limit: "10mb" }));
40	app.use(express.urlencoded({ extended: true }));
41	
42	app.use(clerkMiddleware());
43	
44	// Upsert authenticated user into app_users on every authenticated request.
45	app.use(async (req: Request, _res: Response, next: NextFunction) => {
46	  try {
47	    const { userId, sessionClaims } = getAuth(req);
48	    if (userId) {
49	      const claims = sessionClaims as
50	        | {
51	            email?: string;
52	            primary_email_address?: string;
53	            firstName?: string;
54	            first_name?: string;
55	            lastName?: string;
56	            last_name?: string;
57	            imageUrl?: string;
58	            image_url?: string;
59	          }
60	        | undefined;
61	      const email =
62	        claims?.email ?? claims?.primary_email_address ?? null;
63	      const firstName = claims?.firstName ?? claims?.first_name ?? null;
64	      const lastName = claims?.lastName ?? claims?.last_name ?? null;
65	      const imageUrl = claims?.imageUrl ?? claims?.image_url ?? null;
66	
67	      const existing = await db
68	        .select()
69	        .from(appUsers)
70	        .where(eq(appUsers.clerkUserId, userId));
71	      if (existing.length === 0) {
72	        // First user gets admin
73	        const total = await db.select().from(appUsers);
74	        const role = total.length === 0 ? "admin" : "user";
75	        const [newUser] = await db.insert(appUsers).values({
76	          clerkUserId: userId,
77	          email,
78	          firstName,
79	          lastName,
80	          imageUrl,
81	          role,
82	        }).returning();
83	        // Activate any pending workspace invitations for this email.
84	        if (newUser && email) {
85	          await db
86	            .update(workspaceMembers)
87	            .set({ userId: newUser.id, status: "active", joinedAt: new Date() })
88	            .where(
89	              and(
90	                eq(workspaceMembers.invitedEmail, email),
91	                eq(workspaceMembers.status, "pending"),
92	              ),
93	            );
94	        }
95	      } else if (
96	        email !== existing[0]!.email ||
97	        firstName !== existing[0]!.firstName ||
98	        lastName !== existing[0]!.lastName ||
99	        imageUrl !== existing[0]!.imageUrl
100	      ) {
101	        await db
102	          .update(appUsers)
103	          .set({ email, firstName, lastName, imageUrl })
104	          .where(eq(appUsers.clerkUserId, userId));
105	      }
106	    }
107	  } catch (err) {
108	    req.log.error({ err }, "user upsert failed");
109	  }
110	  next();
111	});
112	
113	app.use("/api", router);
114	
115	export default app;
116	

