124	    db.select({ c }).from(tasks).where(eq(tasks.projectId, projectId)),
125	    db.select({ c }).from(chatMessages).where(eq(chatMessages.projectId, projectId)),
126	    db.select({ c }).from(researchItems).where(eq(researchItems.projectId, projectId)),
127	    db.select({ c }).from(assets).where(eq(assets.projectId, projectId)),
128	    db.select({ c }).from(playtestSessions).where(eq(playtestSessions.projectId, projectId)),
129	  ]);
130	  res.json(
131	    schemas.GetProjectStatsResponse.parse({
132	      entityCount: entityRow?.c ?? 0,
133	      ruleCount: ruleRow?.c ?? 0,
134	      playerCount: playerRow?.c ?? 0,
135	      noteCount: noteRow?.c ?? 0,
136	      taskCount: taskRow?.c ?? 0,
137	      chatMessageCount: chatRow?.c ?? 0,
138	      researchCount: researchRow?.c ?? 0,
139	      assetCount: assetRow?.c ?? 0,
140	      playtestCount: playtestRow?.c ?? 0,
141	    }),
142	  );
143	});
