1	import { Router, type IRouter } from "express";
2	import { eq } from "drizzle-orm";
3	import { db, entities, entityProperties, rules } from "@workspace/db";
4	import { schemas } from "@workspace/api-zod";
5	
6	const router: IRouter = Router();
7	
8	router.get(
9	  "/projects/:projectId/balance",
10	  async (req, res): Promise<void> => {
11	    const params = schemas.GetBalanceReportParams.safeParse(req.params);
12	    if (!params.success) {
13	      res.status(400).json({ error: params.error.message });
14	      return;
15	    }
16	    const projectId = params.data.projectId;
17	    const ents = await db
18	      .select()
19	      .from(entities)
20	      .where(eq(entities.projectId, projectId));
21	    const props: Array<{
22	      entityId: number;
23	      entityName: string;
24	      name: string;
25	      value: number;
26	    }> = [];
27	    for (const e of ents) {
28	      const ps = await db
29	        .select()
30	        .from(entityProperties)
31	        .where(eq(entityProperties.entityId, e.id));
32	      for (const p of ps) {
33	        if (p.value !== null) {
34	          props.push({
35	            entityId: e.id,
36	            entityName: e.name,
37	            name: p.name,
38	            value: p.value,
39	          });
40	        }
41	      }
42	    }
43	    const byName = new Map<
44	      string,
45	      Array<{ entityId: number; entityName: string; value: number }>
46	    >();
47	    for (const p of props) {
48	      const arr = byName.get(p.name) ?? [];
49	      arr.push({ entityId: p.entityId, entityName: p.entityName, value: p.value });
50	      byName.set(p.name, arr);
51	    }
52	    const statSeries = Array.from(byName.entries()).map(([statName, entries]) => ({
53	      statName,
54	      entries,
55	    }));
56	
57	    const rs = await db.select().from(rules).where(eq(rules.projectId, projectId));
58	    let conflictCount = 0;
59	    const titles = new Map<string, number>();
60	    for (const r of rs) {
61	      const k = r.title.toLowerCase().trim();
62	      titles.set(k, (titles.get(k) ?? 0) + 1);
63	    }
64	    for (const v of titles.values()) if (v > 1) conflictCount += v - 1;
65	
66	    let balanceScore = 80;
67	    for (const s of statSeries) {
68	      const vals = s.entries.map((e) => e.value);
69	      const max = Math.max(...vals);
70	      const min = Math.min(...vals);
71	      const spread = max - min;
72	      const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
73	      if (mean !== 0 && spread / Math.abs(mean) > 1.5) balanceScore -= 8;
74	    }
75	    balanceScore -= conflictCount * 5;
76	    balanceScore = Math.max(0, Math.min(100, Math.round(balanceScore)));
77	    const verdict =
78	      balanceScore > 70
79	        ? "Well balanced"
80	        : balanceScore > 40
81	          ? "Some imbalance — review high-spread stats"
82	          : "Significant imbalance";
83	
84	    res.json(
85	      schemas.GetBalanceReportResponse.parse({
86	        balanceScore,
87	        verdict,
88	        statSeries,
89	        conflictCount,
90	      }),
91	    );
92	  },
93	);
94	
95	export default router;
96	

