1	import { Router, type IRouter } from "express";
2	import { eq, asc, and } from "drizzle-orm";
3	import {
4	  db,
5	  chatMessages,
6	  projects,
7	  entities,
8	  rules,
9	  players,
10	} from "@workspace/db";
11	import { schemas } from "@workspace/api-zod";
12	import { stream, AiProviderDisabledError } from "../lib/aiRouter";
13	
14	const router: IRouter = Router();
15	
16	const VALID_TABS = new Set([
17	  "overview",
18	  "research",
19	  "ontology",
20	  "players",
21	  "rules",
22	  "simulator",
23	  "assets",
24	  "playtesting",
25	  "tasks",
26	  "balance",
27	  "export",
28	  "notes",
29	  "storyboard",
30	]);
31	
32	function tabFromQuery(q: unknown): string {
33	  const t = typeof q === "string" ? q : "overview";
34	  return VALID_TABS.has(t) ? t : "overview";
35	}
36	
37	router.get("/projects/:projectId/chat", async (req, res): Promise<void> => {
38	  const params = schemas.ListChatMessagesParams.safeParse(req.params);
39	  if (!params.success) {
40	    res.status(400).json({ error: params.error.message });
41	    return;
42	  }
43	  const tab = tabFromQuery(req.query.tab);
44	  const rows = await db
45	    .select()
46	    .from(chatMessages)
47	    .where(
48	      and(
49	        eq(chatMessages.projectId, params.data.projectId),
50	        eq(chatMessages.tab, tab),
51	      ),
52	    )
53	    .orderBy(asc(chatMessages.createdAt));
54	  res.json(schemas.ListChatMessagesResponse.parse(rows));
55	});
56	
57	router.delete("/projects/:projectId/chat", async (req, res): Promise<void> => {
58	  const params = schemas.ClearChatMessagesParams.safeParse(req.params);
59	  if (!params.success) {
60	    res.status(400).json({ error: params.error.message });
61	    return;
62	  }
63	  const tab = tabFromQuery(req.query.tab);
64	  await db
65	    .delete(chatMessages)
66	    .where(
67	      and(
68	        eq(chatMessages.projectId, params.data.projectId),
69	        eq(chatMessages.tab, tab),
70	      ),
71	    );
72	  res.sendStatus(204);
73	});
74	
75	router.post("/projects/:projectId/chat/send", async (req, res): Promise<void> => {
76	  const params = schemas.SendChatMessageParams.safeParse(req.params);
77	  if (!params.success) {
78	    res.status(400).json({ error: params.error.message });
79	    return;
80	  }
81	  const parsed = schemas.SendChatMessageBody.safeParse(req.body);
82	  if (!parsed.success) {
83	    res.status(400).json({ error: parsed.error.message });
84	    return;
85	  }
86	  const projectId = params.data.projectId;
87	  const tab = parsed.data.tab && VALID_TABS.has(parsed.data.tab) ? parsed.data.tab : "overview";
88	  const { content, gameType, genre } = parsed.data;
89	
90	  const [project] = await db
91	    .select()
92	    .from(projects)
93	    .where(eq(projects.id, projectId));
94	  if (!project) {
95	    res.status(404).json({ error: "Project not found" });
96	    return;
97	  }
98	
99	  await db.insert(chatMessages).values({
100	    projectId,
101	    tab,
102	    role: "user",
103	    content,
104	    gameType: gameType ?? null,
105	    genre: genre ?? null,
106	    model: parsed.data.model ?? null,
107	  });
108	
109	  const history = await db
110	    .select()
111	    .from(chatMessages)
112	    .where(
113	      and(eq(chatMessages.projectId, projectId), eq(chatMessages.tab, tab)),
114	    )
115	    .orderBy(asc(chatMessages.createdAt));
116	
117	  const [es, rs, ps] = await Promise.all([
118	    db.select().from(entities).where(eq(entities.projectId, projectId)),
119	    db.select().from(rules).where(eq(rules.projectId, projectId)),
120	    db.select().from(players).where(eq(players.projectId, projectId)),
121	  ]);
122	
123	  const tabPrompts: Record<string, string> = {
124	    overview: "You are an AI Game Architect helping the designer iterate on the game's high-level concept, hook, and pillars.",
125	    research: "You are a research assistant helping the designer explore mechanics, comps, and references.",
126	    ontology: "You are a game systems analyst helping the designer build entity taxonomies and properties.",
127	    players: "You are a player-archetype consultant helping the designer balance asymmetric factions.",
128	    rules: "You are a rules editor helping the designer write tight, unambiguous game rules.",
129	    simulator: "You are a game-balance analyst helping the designer reason about playthroughs and economy.",
130	    assets: "You are an art director helping the designer specify card flavor, themes, and component aesthetics.",
131	    playtesting: "You are a playtest coordinator helping the designer interpret session feedback.",
132	    tasks: "You are a project manager helping the designer triage their backlog.",
133	    balance: "You are a numerical balance analyst.",
134	    export: "You are a publishing assistant helping prepare deliverables.",
135	    notes: "You are a brainstorming partner for free-form design ideas.",
136	    storyboard: "You are a narrative designer helping plan rule variants and branching design directions.",
137	  };
138	
139	  const contextLines: string[] = [];
140	  contextLines.push(
141	    `Project: ${project.name}${project.description ? ` — ${project.description}` : ""}`,
142	  );
143	  if (project.gameType) contextLines.push(`Game type: ${project.gameType}`);
144	  if (project.genre) contextLines.push(`Genre: ${project.genre}`);
145	  if (project.playerCount) contextLines.push(`Player count: ${project.playerCount}`);
146	  if (project.targetDuration) contextLines.push(`Target duration: ${project.targetDuration}`);
147	  if (gameType) contextLines.push(`Current focus — game type: ${gameType}`);
148	  if (genre) contextLines.push(`Current focus — genre: ${genre}`);
149	  if (es.length)
150	    contextLines.push(
151	      `Entities (${es.length}): ${es.slice(0, 12).map((e) => `${e.name} (${e.type})`).join(", ")}`,
152	    );
153	  if (rs.length)
154	    contextLines.push(
155	      `Rules (${rs.length}): ${rs.slice(0, 8).map((r) => r.title).join("; ")}`,
156	    );
157	  if (ps.length)
158	    contextLines.push(
159	      `Players (${ps.length}): ${ps.slice(0, 8).map((p) => `${p.name}${p.role ? ` — ${p.role}` : ""}`).join(", ")}`,
160	    );
161	
162	  const tabIntro = tabPrompts[tab] ?? tabPrompts.overview;
163	  const systemPrompt = `${tabIntro}
164	
165	You are GameForge, an AI co-designer for tabletop board games. Be concise, specific, and opinionated. Prefer short numbered or bulleted lists over walls of prose. Suggest concrete numbers and mechanics rather than vague advice. Use markdown.
166	
167	Current project context:
168	${contextLines.join("\n")}`;
169	
170	  const apiMessages = history.map((m) => ({
171	    role: (m.role === "assistant" ? "assistant" : "user") as "user" | "assistant",
172	    content: m.content,
173	  }));
174	
175	  res.setHeader("Content-Type", "text/event-stream");
176	  res.setHeader("Cache-Control", "no-cache, no-transform");
177	  res.setHeader("Connection", "keep-alive");
178	  res.setHeader("X-Accel-Buffering", "no");
179	  res.flushHeaders?.();
180	
181	  let assistantText = "";
182	  let usedModel = "";
183	  let usedProvider = "";
184	  try {
185	    const result = await stream(req, {
186	      kind: "narrative",
187	      system: systemPrompt,
188	      messages: apiMessages,
189	      maxTokens: 2048,
190	      onChunk: (piece) => {
191	        assistantText += piece;
192	        res.write(`data: ${JSON.stringify({ content: piece })}\n\n`);
193	      },
194	    });
195	    usedModel = result.model;
196	    usedProvider = result.provider;
197	    if (assistantText.length > 0) {
198	      await db.insert(chatMessages).values({
199	        projectId,
200	        tab,
201	        role: "assistant",
202	        content: assistantText,
203	        gameType: gameType ?? null,
204	        genre: genre ?? null,
205	        model: usedModel,
206	        provider: usedProvider,
207	      });
208	    }
209	    res.write(
210	      `data: ${JSON.stringify({ done: true, model: usedModel, provider: usedProvider })}\n\n`,
211	    );
212	    res.end();
213	  } catch (err) {
214	    req.log.error({ err }, "chat stream failed");
215	    const message =
216	      err instanceof AiProviderDisabledError
217	        ? `${err.message} Ask a workspace admin to enable it under AI providers.`
218	        : "AI request failed. Please try again.";
