20	router.post(
21	  "/projects/:projectId/simulator/run",
22	  async (req, res): Promise<void> => {
23	    const params = schemas.RunSimulatorParams.safeParse(req.params);
24	    if (!params.success) {
25	      res.status(400).json({ error: params.error.message });
26	      return;
27	    }
28	    const parsed = schemas.RunSimulatorBody.safeParse(req.body);
29	    if (!parsed.success) {
30	      res.status(400).json({ error: parsed.error.message });
31	      return;
32	    }
33	    const iters = Math.min(Math.max(parsed.data.iterations, 50), 5000);
34	    const turns = Math.min(Math.max(parsed.data.turns, 5), 100);
35	    const start = parsed.data.startingResources ?? 10;
36	    const income = parsed.data.incomePerTurn ?? 3;
37	    const upkeep = parsed.data.upkeepPerTurn ?? 2;
38	    const rand = parsed.data.randomness ?? 1.5;
39	
40	    const perTurn: number[][] = Array.from({ length: turns }, () => []);
41	    const finals: number[] = [];
42	    let bankrupt = 0;
43	    for (let i = 0; i < iters; i += 1) {
44	      let res2 = start;
45	      let dead = false;
46	      for (let t = 0; t < turns; t += 1) {
47	        const noise = (Math.random() * 2 - 1) * rand;
48	        res2 += income - upkeep + noise;
49	        if (res2 < 0) {
50	          dead = true;
51	          res2 = 0;
52	        }
53	        perTurn[t]!.push(res2);
54	      }
55	      finals.push(res2);
56	      if (dead) bankrupt += 1;
57	    }
58	    const finalsSorted = [...finals].sort((a, b) => a - b);
59	    const meanFinal =
60	      finalsSorted.reduce((s, v) => s + v, 0) / finalsSorted.length;
61	    const bankruptRate = bankrupt / iters;
62	    let healthScore = 100;
63	    healthScore -= bankruptRate * 80;
64	    if (meanFinal < 5) healthScore -= 20;
65	    if (meanFinal < 0) healthScore -= 30;
66	    if (rand > 4) healthScore -= 10;
67	    healthScore = Math.max(0, Math.min(100, Math.round(healthScore)));
68	    const verdict =
69	      healthScore > 70
70	        ? "Healthy economy"
71	        : healthScore > 40
72	          ? "Caution — tighten balance"
73	          : "Broken — rework parameters";
74	
75	    const turnsOut = perTurn.map((arr, t) => {
76	      const sorted = [...arr].sort((a, b) => a - b);
77	      return {
78	        turn: t + 1,
79	        p10: Math.round(quantile(sorted, 0.1) * 100) / 100,
80	        p50: Math.round(quantile(sorted, 0.5) * 100) / 100,
81	        p90: Math.round(quantile(sorted, 0.9) * 100) / 100,
82	      };
83	    });
84	
85	    res.json(
86	      schemas.RunSimulatorResponse.parse({
87	        healthScore,
88	        verdict,
89	        meanFinal: Math.round(meanFinal * 100) / 100,
90	        bankruptRate: Math.round(bankruptRate * 1000) / 1000,
91	        turns: turnsOut,
92	      }),
93	    );
94	  },
