361	// Pick string fields from a parsed AI JSON response, tolerating wrapped
362	// shapes such as {"player": {...}}, {"data": {...}}, or {"result": {...}}.
363	// If no allowed keys are found at the top level, looks EXACTLY one level
364	// deep into immediate child object values and returns the first match.
365	// Does not recurse further — deeper matches are intentionally ignored to
366	// avoid pulling allowed-key names from unrelated nested noise.
367	// Empty strings are skipped.
368	export function pickStringFields(
369	  obj: unknown,
370	  allowed: readonly string[],
371	): Record<string, string> {
372	  const pickFlat = (v: unknown): Record<string, string> => {
373	    const result: Record<string, string> = {};
374	    if (!v || typeof v !== "object" || Array.isArray(v)) return result;
375	    const rec = v as Record<string, unknown>;
376	    for (const k of allowed) {
377	      const val = rec[k];
378	      if (typeof val === "string" && val.trim().length > 0) {
379	        result[k] = val;
380	      } else if (typeof val === "number" || typeof val === "boolean") {
381	        result[k] = String(val);
382	      }
383	    }
384	    return result;
385	  };
386	  const top = pickFlat(obj);
387	  if (Object.keys(top).length > 0) return top;
388	  if (!obj || typeof obj !== "object" || Array.isArray(obj)) return top;
389	  for (const child of Object.values(obj as Record<string, unknown>)) {
390	    const nested = pickFlat(child);
391	    if (Object.keys(nested).length > 0) return nested;
392	  }
393	  return top;
394	}
