148	export async function upsertWorkspaceProviderSettings(
149	  workspaceId: number,
150	  provider: WorkspaceProvider,
151	  patch: { enabled?: boolean; apiKey?: string | null },
152	): Promise<{ provider: WorkspaceProvider; enabled: boolean; hasKey: boolean }> {
153	  const [existing] = await db
154	    .select()
155	    .from(workspaceAiSettings)
156	    .where(
157	      and(
158	        eq(workspaceAiSettings.workspaceId, workspaceId),
159	        eq(workspaceAiSettings.provider, provider),
160	      ),
161	    );
162	
163	  let encryptedKey: string | null | undefined = undefined;
164	  if (patch.apiKey === null) encryptedKey = null;
165	  else if (typeof patch.apiKey === "string" && patch.apiKey.trim().length > 0) {
166	    encryptedKey = encryptApiKey(patch.apiKey.trim());
167	  }
168	
169	  if (!existing) {
170	    const [created] = await db
171	      .insert(workspaceAiSettings)
172	      .values({
173	        workspaceId,
174	        provider,
175	        enabled: patch.enabled ?? true,
176	        encryptedKey: encryptedKey ?? null,
177	      })
178	      .returning();
179	    return { provider, enabled: created.enabled, hasKey: !!created.encryptedKey };
180	  }
181	
182	  const updates: Partial<typeof workspaceAiSettings.$inferInsert> = {};
183	  if (patch.enabled !== undefined) updates.enabled = patch.enabled;
184	  if (encryptedKey !== undefined) updates.encryptedKey = encryptedKey;
185	  if (Object.keys(updates).length === 0) {
186	    return { provider, enabled: existing.enabled, hasKey: !!existing.encryptedKey };
187	  }
188	  const [updated] = await db
189	    .update(workspaceAiSettings)
190	    .set(updates)
191	    .where(eq(workspaceAiSettings.id, existing.id))
192	    .returning();
193	  return { provider, enabled: updated.enabled, hasKey: !!updated.encryptedKey };
194	}
