1	import pLimit from "p-limit";
2	import pRetry, { AbortError } from "p-retry";
3	
4	/**
5	 * Batch Processing Utilities
6	 *
7	 * Generic batch processing with built-in rate limiting and automatic retries.
8	 */
9	
10	export interface BatchOptions {
11	  concurrency?: number;
12	  retries?: number;
13	  minTimeout?: number;
14	  maxTimeout?: number;
15	  onProgress?: (completed: number, total: number, item: unknown) => void;
16	}
17	
18	export function isRateLimitError(error: unknown): boolean {
19	  const errorMsg = error instanceof Error ? error.message : String(error);
20	  return (
21	    errorMsg.includes("429") ||
22	    errorMsg.includes("RATELIMIT_EXCEEDED") ||
23	    errorMsg.toLowerCase().includes("quota") ||
24	    errorMsg.toLowerCase().includes("rate limit")
25	  );
26	}
27	
28	export async function batchProcess<T, R>(
29	  items: T[],
30	  processor: (item: T, index: number) => Promise<R>,
31	  options: BatchOptions = {}
32	): Promise<R[]> {
33	  const {
34	    concurrency = 2,
35	    retries = 7,
36	    minTimeout = 2000,
37	    maxTimeout = 128000,
38	    onProgress,
39	  } = options;
40	
41	  const limit = pLimit(concurrency);
42	  let completed = 0;
43	
44	  const promises = items.map((item, index) =>
45	    limit(() =>
46	      pRetry(
47	        async () => {
48	          try {
49	            const result = await processor(item, index);
50	            completed++;
51	            onProgress?.(completed, items.length, item);
52	            return result;
53	          } catch (error: unknown) {
54	            if (isRateLimitError(error)) {
55	              throw error;
56	            }
57	            throw new AbortError(
58	              error instanceof Error ? error : new Error(String(error))
59	            );
60	          }
61	        },
62	        { retries, minTimeout, maxTimeout, factor: 2 }
63	      )
64	    )
65	  );
66	
67	  return Promise.all(promises);
68	}
69	
70	export async function batchProcessWithSSE<T, R>(
71	  items: T[],
72	  processor: (item: T, index: number) => Promise<R>,
73	  sendEvent: (event: { type: string; [key: string]: unknown }) => void,
74	  options: Omit<BatchOptions, "concurrency" | "onProgress"> = {}
75	): Promise<R[]> {
76	  const { retries = 5, minTimeout = 1000, maxTimeout = 15000 } = options;
77	
78	  sendEvent({ type: "started", total: items.length });
79	
80	  const results: R[] = [];
81	  let errors = 0;
82	
83	  for (let index = 0; index < items.length; index++) {
84	    const item = items[index];
85	    sendEvent({ type: "processing", index, item });
86	
87	    try {
88	      const result = await pRetry(
89	        () => processor(item, index),
90	        {
91	          retries,
92	          minTimeout,
93	          maxTimeout,
94	          factor: 2,
95	          onFailedAttempt: (error) => {
96	            if (!isRateLimitError(error)) {
97	              throw new AbortError(
98	                error instanceof Error ? error : new Error(String(error))
99	              );
100	            }
101	          },
102	        }
103	      );
104	      results.push(result);
105	      sendEvent({ type: "progress", index, result });
106	    } catch (error) {
107	      errors++;
108	      results.push(undefined as R);
109	      sendEvent({
110	        type: "error",
111	        index,
112	        error: error instanceof Error ? error.message : String(error),
113	      });
114	    }
115	  }
116	
117	  sendEvent({ type: "completed", total: items.length, errors });
118	  return results;
119	}
