55	async function request<T>(path: string, init?: RequestInit): Promise<T> {
56	  const res = await fetch(`${apiBase()}/api${path}`, {
57	    credentials: "include",
58	    headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) },
59	    ...init,
60	  });
61	  if (!res.ok) {
62	    const text = await res.text();
63	    let parsed: { error?: string } | null = null;
64	    try { parsed = JSON.parse(text); } catch { /* ignore */ }
65	    throw new Error(parsed?.error || text || `HTTP ${res.status}`);
66	  }
67	  if (res.status === 204) return undefined as T;
68	  return (await res.json()) as T;
69	}
