24	export function useCollaboration(projectId: number) {
25	  const { user } = useUser();
26	  const [connectedUsers, setConnectedUsers] = useState<PresenceUser[]>([]);
27	  const [isOnline, setIsOnline] = useState(false);
28	  const ydocRef = useRef<Y.Doc | null>(null);
29	  const wsProviderRef = useRef<WebsocketProvider | null>(null);
30	  const idbProviderRef = useRef<IndexeddbPersistence | null>(null);
31	
32	  useEffect(() => {
33	    if (!user || !projectId) return;
34	
35	    // Initialize Yjs document
36	    const ydoc = new Y.Doc();
37	    ydocRef.current = ydoc;
38	
39	    // Set up IndexedDB for offline persistence
40	    const idbProvider = new IndexeddbPersistence(`gameforge-project-${projectId}`, ydoc);
41	    idbProviderRef.current = idbProvider;
42	
43	    idbProvider.whenSynced.then(() => {
44	      console.log("Document loaded from IndexedDB");
45	    });
46	
47	    // Set up WebSocket provider for real-time collaboration
48	    const wsUrl = import.meta.env.VITE_WS_URL || "ws://localhost:1234";
49	    const wsProvider = new WebsocketProvider(
50	      wsUrl,
51	      `gameforge-project-${projectId}`,
52	      ydoc,
53	      {
54	        connect: true,
55	        params: {
56	          userId: user.id,
57	          firstName: user.firstName || "",
58	          lastName: user.lastName || "",
59	          imageUrl: user.imageUrl || "",
60	        },
61	      }
62	    );
63	    wsProviderRef.current = wsProvider;
64	
65	    // Set up awareness for presence
66	    const awareness = wsProvider.awareness;
67	    const localUserState = {
68	      userId: user.id,
69	      firstName: user.firstName,
70	      lastName: user.lastName,
71	      imageUrl: user.imageUrl,
72	      color: getUserColor(user.id),
73	      cursor: null,
74	      selection: null,
75	      lastSeen: new Date().toISOString(),
76	    };
77	    awareness.setLocalStateField("user", localUserState);
78	
79	    // Handle connection status
80	    wsProvider.on("status", (event: { status: string }) => {
81	      setIsOnline(event.status === "connected");
82	    });
83	
84	    // Handle awareness changes (other users joining/leaving/updating)
85	    const handleAwarenessChange = () => {
86	      const states = awareness.getStates();
87	      const users: PresenceUser[] = [];
88	      
89	      states.forEach((state: unknown, clientId: number) => {
90	        const stateData = state as { user?: PresenceUser; lastSeen?: string };
91	        const userState = stateData.user;
92	        if (userState && userState.userId !== user.id) {
93	          users.push({
94	            ...userState,
95	            lastSeen: stateData.lastSeen || new Date().toISOString(),
96	          });
97	        }
98	      });
99	      
100	      setConnectedUsers(users);
101	    };
102	
103	    awareness.on("change", handleAwarenessChange);
104	
105	    // Initial sync
106	    handleAwarenessChange();
107	
108	    // Cleanup
109	    return () => {
110	      awareness.off("change", handleAwarenessChange);
111	      wsProvider.destroy();
112	      idbProvider.destroy();
113	      ydoc.destroy();
114	    };
115	  }, [user, projectId]);
116	
117	  // Function to update cursor position
118	  const updateCursor = useCallback((x: number, y: number, visible: boolean = true) => {
119	    if (!wsProviderRef.current) return;
120	    const awareness = wsProviderRef.current.awareness;
121	    const currentUser = awareness.getLocalState()?.user as PresenceUser | undefined;
122	    if (currentUser) {
123	      awareness.setLocalStateField("user", {
124	        ...currentUser,
125	        cursor: { x, y, visible },
126	        lastSeen: new Date().toISOString(),
127	      });
128	    }
129	  }, []);
130	
131	  // Function to update selection
132	  const updateSelection = useCallback((entityType: string, entityId: number | null) => {
133	    if (!wsProviderRef.current) return;
134	    const awareness = wsProviderRef.current.awareness;
135	    const currentUser = awareness.getLocalState()?.user as PresenceUser | undefined;
136	    if (currentUser) {
137	      awareness.setLocalStateField("user", {
138	        ...currentUser,
139	        selection: { entityType, entityId },
140	        lastSeen: new Date().toISOString(),
141	      });
142	    }
143	  }, []);
144	
145	  // Function to hide cursor
146	  const hideCursor = useCallback(() => {
147	    if (!wsProviderRef.current) return;
148	    const awareness = wsProviderRef.current.awareness;
149	    const currentUser = awareness.getLocalState()?.user as PresenceUser | undefined;
150	    if (currentUser) {
151	      awareness.setLocalStateField("user", {
152	        ...currentUser,
153	        cursor: { x: 0, y: 0, visible: false },
154	        lastSeen: new Date().toISOString(),
155	      });
156	    }
157	  }, []);
158	
159	  return {
160	    connectedUsers,
161	    isOnline,
162	    updateCursor,
163	    updateSelection,
164	    hideCursor,
165	    ydoc: ydocRef.current,
166	  };
167	}
