429	        .where(eq(projectVersions.id, v2))
430	        .limit(1);
431	      if (!version1 || !version2) {
432	        res.status(404).json({ error: "One or more versions not found" });
433	        return;
434	      }
435	      // `snapshot` is a JSONB column typed as `unknown` — narrow with a Record
436	      // cast since we just compare presence of the four known top-level keys.
437	      const s1 = (version1.snapshot ?? {}) as Record<string, unknown>;
438	      const s2 = (version2.snapshot ?? {}) as Record<string, unknown>;
439	      const diff = {
440	        entities: JSON.stringify(s1.entities) !== JSON.stringify(s2.entities),
441	        rules: JSON.stringify(s1.rules) !== JSON.stringify(s2.rules),
442	        players: JSON.stringify(s1.players) !== JSON.stringify(s2.players),
443	        notes: JSON.stringify(s1.notes) !== JSON.stringify(s2.notes),
444	      };
445	      res.json({ diff });
446	    } catch (err) {
447	      req.log.error({ err }, "compare versions failed");
448	      res.status(500).json({ error: "Failed to compare versions" });
449	    }
